class Solution {
public:
    int countGoodRotations(vector<int>& nums) {
        int n = nums.size(), half = n / 2;
        long long total = 0, window = 0;
        for (int x : nums) total += x;
        for (int i = 0; i < half; ++i) window += nums[i];
        int ans = 0;
        for (int start = 0; start < n; ++start) {
            if (2 * window > total) ++ans;
            window -= nums[start];
            window += nums[(start + half) % n];
        }
        return ans;
    }
};
